группа('body-layers: ощущения и одежда');
{
  const L = await модуль('render/body-layers.js');
  const о = L.ощущенияИзТекста('жарко, пересохло во рту, тянет внизу живота, ноги ватные, лёгкий хмель от вина', 'сердце колотится, ноет поясница');
  равно('органы по тексту', о.map(x => x.id).sort(), ['back', 'head', 'heart', 'legs', 'lowbelly', 'throat']);
  проверить('«лёгкий хмель» — голова, не лёгкие', о.find(x => x.id === 'head').куски.includes('лёгкий хмель от вина'));
  проверить('«жарко» без органа не попадает', !о.some(x => x.куски.includes('жарко')));
  равно('пусто — пусто', L.ощущенияИзТекста('empty', ''), []);
  const вещи = (t) => L.одеждаИзТекста(t).map(x => [x.id, x.состояние]);
  равно('платье расстёгнуто, чулки, туфли сброшены', вещи('тёмно-синее платье расстёгнуто до пояса, чулки, туфли сброшены у дивана'), [['dress', 'half'], ['stockings', 'on'], ['shoes', 'off']]);
  равно('рубашка на полу, джинсы расстёгнуты', вещи('рубашка на полу, джинсы расстёгнуты'), [['top', 'off'], ['pants', 'half']]);
  равно('«без рукавов» — не «снято»; босиком — обуви нет', вещи('платье без рукавов, босиком'), [['dress', 'on'], ['shoes', 'off']]);
  равно('носки — чулочный слой', вещи('футболка, шерстяные носки'), [['top', 'on'], ['stockings', 'on']]);
  проверить('у каждой вещи есть область на силуэте', L.ВЕЩИ.every(([id]) => L.ОБЛАСТИ[id]));
}

