группа('подсветка кода');
{
  const Sk = await модуль('skip-highlight.js');
  const код = (перед, тег = 'PRE', вСообщении = true) => ({ parentElement: { tagName: тег, previousElementSibling: перед === null ? null : { textContent: перед } }, closest: () => вСообщении });
  проверить('блок сразу за [HUD] — свой', Sk.блокHUD(код('текст ответа\n[HUD]\n')));
  проверить('обычный блок кода — нет', !Sk.блокHUD(код('вот пример')) && !Sk.блокHUD(код(null)));
  проверить('вне сообщения — нет', !Sk.блокHUD(код('[HUD]', 'PRE', false)));
  const вызовы = [];
  const hljs = { highlightElement(э) { вызовы.push(э); return 'да'; } };
  Sk.подключитьПропускПодсветки(hljs);
  Sk.подключитьПропускПодсветки(hljs);
  const чужой = код('вот пример');
  проверить('свой блок пропущен, чужой раскрашен один раз', hljs.highlightElement(код('[HUD]')) === undefined && hljs.highlightElement(чужой) === 'да' && вызовы.length === 1 && вызовы[0] === чужой);
  проверить('нет подсветки — не падает', Sk.подключитьПропускПодсветки(null) === undefined);
}

